mapper.select:
SELECT org_id, daily_token_limit
FROM organization_ai_budget
WHERE org_id = #{orgId}

SELECT COALESCE(MAX(consumed_tokens), 0)
FROM organization_ai_budget_usage
WHERE org_id = #{orgId} AND usage_day = #{usageDay}

SELECT COALESCE(SUM(reserved_tokens), 0)
FROM organization_ai_budget_reservation
WHERE org_id = #{orgId} AND usage_day = #{usageDay}

mapper.update:
UPDATE organization_ai_budget_usage
SET consumed_tokens = consumed_tokens + #{consumedTokens}
WHERE org_id = #{orgId} AND usage_day = #{usageDay}
